import axios from "axios";

const API = axios.create({ baseURL: "http://localhost:3001" }); // Replace with your backend URL

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    const token = localStorage.getItem("authToken"); // Consistent token retrieval
    if (token) {
        req.headers.Authorization = `Bearer ${token}`;
    }
    return req;
});

// Authentication APIs
export const loginUser = async ({ username, password }) => {
    try {
        const response = await API.post('/api/login', { username, password });
        return response.data; // Assuming response structure: { data: { token, user }}
    } catch (error) {
        console.error("Login failed:", error);
        throw error; // Rethrow the error so you can handle it in the component
    }
};

// Franchise APIs
export const createFranchise = (data) => API.post("/franchises", data);
export const getFranchises = () => API.get("/dashboard");
export const deleteFranchise = (id) => API.delete(`/franchises/${id}`);
export const updateFranchise = (id, data) => API.put(`/franchises/${id}`, data); // New function for updating a franchise

// User APIs
export const createUser = (data) => API.post("/users", data);

// Function to get users
export const getUsers = async () => {
    try {
        const response = await API.get("/users");
        return response.data;
    } catch (error) {
        console.error("Error fetching users:", error);
        throw error;
    }
};

// Function to delete a user by ID
export const deleteUser = async (userId) => {
    try {
        const response = await API.delete(`/users/${userId}`);
        return response.data;
    } catch (error) {
        console.error("Error deleting user:", error);
        throw error;
    }
};

// Function to update a user by ID (No need to manually attach the token here anymore)
export const updateUser = async (userId, updatedData) => {
    try {
        const response = await API.put(`/users/${userId}`, updatedData);
        return response.data;
    } catch (error) {
        console.error("Error updating user:", error);
        throw error;
    }
};


// Update Exam Data APIs for a franchise
export const updateExamData = (franchiseId, data) => API.put(`/franchises/${franchiseId}/exam-data`, data);
